diff --git a/node/safe-merge/index.mjs b/node/safe-merge/index.mjs
index 5597dc3..8504990 100644
--- a/node/safe-merge/index.mjs
+++ b/node/safe-merge/index.mjs
@@ -1,3 +1,113 @@
+const BANNED_KEYS = new Set(["__proto__", "prototype", "constructor"]);
+
+function isPlainObject(value) {
+  if (typeof value !== "object" || value === null) return false;
+  const proto = Object.getPrototypeOf(value);
+  return proto === Object.prototype || proto === null;
+}
+
+function deepClone(value, seen = new WeakMap()) {
+  if (value === null || typeof value !== "object") return value;
+
+  if (seen.has(value)) return seen.get(value);
+
+  if (Array.isArray(value)) {
+    const result = [];
+    seen.set(value, result);
+    for (const item of value) result.push(deepClone(item, seen));
+    return result;
+  }
+
+  if (value instanceof Date) {
+    return new Date(value.getTime());
+  }
+
+  if (value instanceof RegExp) {
+    return new RegExp(value.source, value.flags);
+  }
+
+  if (value instanceof Map) {
+    const result = new Map();
+    seen.set(value, result);
+    for (const [key, val] of value) {
+      result.set(deepClone(key, seen), deepClone(val, seen));
+    }
+    return result;
+  }
+
+  if (value instanceof Set) {
+    const result = new Set();
+    seen.set(value, result);
+    for (const item of value) {
+      result.add(deepClone(item, seen));
+    }
+    return result;
+  }
+
+  if (value instanceof ArrayBuffer) {
+    return value.slice(0);
+  }
+
+  if (ArrayBuffer.isView(value)) {
+    // TypedArrays and DataView
+    if (value instanceof DataView) {
+      return new DataView(value.buffer.slice(0), value.byteOffset, value.byteLength);
+    }
+    return value.slice();
+  }
+
+  // Plain objects and generic class instances: recreate with the same
+  // prototype and clone own properties (enumerable or not, string or
+  // symbol keyed) via property descriptors, so setters aren't invoked
+  // and data integrity is preserved. Banned keys are dropped.
+  const proto = Object.getPrototypeOf(value);
+  const result = Object.create(proto);
+  seen.set(value, result);
+  const descriptors = Object.getOwnPropertyDescriptors(value);
+  for (const key of Reflect.ownKeys(descriptors)) {
+    if (typeof key === "string" && BANNED_KEYS.has(key)) continue;
+    const descriptor = descriptors[key];
+    if ("value" in descriptor) {
+      descriptor.value = deepClone(descriptor.value, seen);
+    }
+    Object.defineProperty(result, key, descriptor);
+  }
+  return result;
+}
+
+function mergeValue(base, patch, seen = new WeakMap()) {
+  if (isPlainObject(base) && isPlainObject(patch)) {
+    let baseMap = seen.get(base);
+    if (!baseMap) {
+      baseMap = new WeakMap();
+      seen.set(base, baseMap);
+    } else if (baseMap.has(patch)) {
+      return baseMap.get(patch);
+    }
+
+    const proto = Object.getPrototypeOf(base);
+    const result = Object.create(proto);
+    baseMap.set(patch, result);
+
+    const keys = new Set([...Object.keys(base), ...Object.keys(patch)]);
+    for (const key of keys) {
+      if (BANNED_KEYS.has(key)) continue;
+      if (Object.prototype.hasOwnProperty.call(patch, key)) {
+        const patchValue = patch[key];
+        const baseValue = base[key];
+        result[key] =
+          isPlainObject(baseValue) && isPlainObject(patchValue)
+            ? mergeValue(baseValue, patchValue, seen)
+            : deepClone(patchValue);
+      } else {
+        result[key] = deepClone(base[key]);
+      }
+    }
+    return result;
+  }
+  return deepClone(patch);
+}
+
 export function safeMerge(base, patch) {
-  return { ...base, ...patch };
+  return mergeValue(base, patch);
 }
